import{_ as t,c as a,o as i,ah as s}from"./chunks/framework.CdwlI3v5.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"_layout":"writeup","ctf":"ISITDTU Quals 2018","chal":"Baby","flag":"ISITDTU{bit\\\\_flipping\\\\_is\\\\_fun}","points":271,"category":"crypto"},"headers":[],"relativePath":"writeups/2018/ISITDTU Quals 2018/Baby/2018-07-28-Baby.md","filePath":"writeups/2018/ISITDTU Quals 2018/Baby/2018-07-28-Baby.md"}'),o={name:"writeups/2018/ISITDTU Quals 2018/Baby/2018-07-28-Baby.md"};function h(l,e,n,r,p,c){return i(),a("div",null,[...e[0]||(e[0]=[s('<blockquote><p>nc 35.185.178.212 33337 or nc 35.185.178.212 33338</p></blockquote><p>We are given a <a href="./baby.py">baby.py</a></p><p>It looks like the server just sha512s (flag|input) and then sends the hash to us, which allows for a very simple exploit.</p><h2 id="exploit" tabindex="-1">Exploit <a class="header-anchor" href="#exploit" aria-label="Permalink to “Exploit”">​</a></h2><p>First, we send 0, obtaining the sha512 of the flag.</p><p>Next, we send 2^(i-1), checking if the hash changed, if the hash changed, then set the ith bit of the flag to 0, else if the hash is still the same, set the ith bit of the flag to 1</p><h3 id="logic" tabindex="-1">Logic <a class="header-anchor" href="#logic" aria-label="Permalink to “Logic”">​</a></h3><p>Consider a simple flag 0b01</p><p>First, we send 0, obtaining the sha512 of 0b1001</p><p>Next, we send 0b1, we get the sha512 hash of 0b1001|0b1=0b1001, which did not change. The only way it won&#39;t change is if the OR operation did not affect our flag, or more mathematically, FLAG|INPUT=FLAG. Since 1|1=1 and 0|1=1, the first bit must be 1</p><p>Next, we send 0b10, we get the sha512 hash of 0b1001|0b10=0b1011, which is different(only one bit changed, idt it&#39;s possible to hash collide?). Therefore the second bit is 0.</p><p>We continue this till we obtain every bit of the flag.</p><p><a href="./exploit.py">exploit</a></p><p>p.s. the server response is incredible, probably the fastest I&#39;ve ever seen, especially for such a challenge where you have to solve bit by bit</p>',14)])])}const d=t(o,[["render",h]]);export{f as __pageData,d as default};
